DO $test$
DECLARE u uuid;reviewer uuid;bid uuid:=gen_random_uuid();plan uuid;emp uuid:=gen_random_uuid();rid uuid;req uuid:=gen_random_uuid();payload jsonb;entry jsonb;r jsonb;rev timestamptz;hash text;denied boolean;cfg jsonb;counts bigint;
BEGIN
 IF public.frindly_market_environment_status()->>'project_ref' IS DISTINCT FROM 'smvvevrtjqkflyqkyape' THEN RAISE EXCEPTION 'Market only';END IF;
 SELECT id INTO u FROM auth.users a WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;
 SELECT id INTO reviewer FROM auth.users a WHERE id<>u AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;
 SELECT id INTO plan FROM public.plans WHERE 'payroll'=ANY(included_modules) ORDER BY cardinality(included_modules) DESC NULLS LAST LIMIT 1;
 IF u IS NULL OR reviewer IS NULL OR plan IS NULL THEN RAISE EXCEPTION 'Fixture prerequisites missing';END IF;
 BEGIN
  INSERT INTO public.businesses(id,name) VALUES(bid,'Market pay-run atomic fixture');
  INSERT INTO public.profiles(id,business_id,active_business_id,full_name,role,is_super_admin) VALUES(u,bid,bid,'Maker fixture','owner',false),(reviewer,bid,bid,'Reviewer fixture','admin',false);
  INSERT INTO public.business_memberships(business_id,user_id,role,status) VALUES(bid,u,'owner','active'),(bid,reviewer,'admin','active');
  INSERT INTO public.subscriptions(business_id,plan_id,status,current_period_end,trial_ends_at) VALUES(bid,plan,'trialing',now()+interval '30 days',now()+interval '30 days');
  INSERT INTO public.payroll_employees(id,business_id,employee_number,first_name,last_name,pay_type) VALUES(emp,bid,'FIXTURE','Payrun','Fixture','hourly');
  INSERT INTO public.accounting_periods(business_id,period_start,period_end,financial_year,status) VALUES(bid,'2026-04-01','2027-03-31',2027,'open');
  PERFORM set_config('request.jwt.claim.sub',u::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  EXECUTE 'SET LOCAL ROLE authenticated';
  entry:=jsonb_build_object('employee_id',emp,'employee_snapshot',jsonb_build_object('name','Fixture','employee_number','FIXTURE'),'hours',10,'rate',10,'ordinary_earnings',100,'holiday_pay',0,'allowances',0,'reimbursements',0,'gross_pay',100,'paye',20,'kiwisaver_employee',0,'student_loan',0,'other_deductions',0,'total_deductions',20,'net_pay',80,'kiwisaver_employer_gross',0,'esct',0,'employer_contributions',0,'total_employment_cost',100,'calculation_snapshot',jsonb_build_object('p7_tax',jsonb_build_object('status','calculated')));
  payload:=jsonb_build_object('run',jsonb_build_object('pay_run_number','FIXTURE-RUN','pay_frequency','weekly','period_start','2026-10-01','period_end','2026-10-07','pay_date','2026-10-08','country_code','NZ','currency','NZD','rules_snapshot','{}'::jsonb,'gross_pay',100,'total_deductions',20,'net_pay',80,'employer_contributions',0,'total_employment_cost',100),
   'employees',jsonb_build_array(jsonb_build_object('employee',entry,'lines','[]'::jsonb,'payslip',jsonb_build_object('number','FIXTURE-RUN-FIXTURE','data',jsonb_build_object('pay',jsonb_build_object('gross',100,'paye',20,'net',80))))),
   'financial',jsonb_build_array(jsonb_build_object('type','wage_expense','amount',100),jsonb_build_object('type','paye_payable','amount',20),jsonb_build_object('type','net_wages_payable','amount',80),jsonb_build_object('type','total_employment_cost','amount',100)),'finalise',false);
  r:=public.v6226_save_pay_run(req,NULL,NULL,payload);rid:=(r->'run'->>'id')::uuid;rev:=(r->'run'->>'updated_at')::timestamptz;
  IF r->'run'->>'status'<>'calculated' OR (SELECT count(*) FROM public.payroll_pay_run_employees WHERE pay_run_id=rid)<>1 THEN RAISE EXCEPTION 'Draft save incomplete';END IF;
  PERFORM public.v6226_save_pay_run(req,NULL,NULL,payload);
  IF (SELECT count(*) FROM public.payroll_pay_runs WHERE business_id=bid)<>1 THEN RAISE EXCEPTION 'Retry duplicated pay run';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev-interval '1 second',payload);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale run accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(payload,'{employees}',(payload->'employees')||jsonb_build_array(jsonb_build_object('employee',jsonb_set(entry,'{employee_id}',to_jsonb(gen_random_uuid())),'lines','[]'::jsonb))));EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  IF NOT denied OR (SELECT count(*) FROM public.payroll_pay_run_employees WHERE pay_run_id=rid)<>1 OR (SELECT updated_at FROM public.payroll_pay_runs WHERE id=rid)<>rev THEN RAISE EXCEPTION 'Failed replacement left partial pay run';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(payload,'{run,gross_pay}','"NaN"'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Non-finite payroll amount accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(payload,'{employees,0,lines}',jsonb_build_array(jsonb_build_object('timesheet_id',gen_random_uuid(),'line_type','ordinary','quantity',10,'rate',10,'amount',100))));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Unavailable timesheet accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(jsonb_set(payload,'{finalise}','true'),'{run,pay_date}','"2000-01-01"'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Uncovered pay date accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(jsonb_set(payload,'{finalise}','true'),'{employees,0,payslip}','null'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Missing payslip accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(jsonb_set(payload,'{finalise}','true'),'{financial}',(payload->'financial')||jsonb_build_array(payload->'financial'->0)));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Duplicate financial entries accepted';END IF;
  IF (SELECT updated_at FROM public.payroll_pay_runs WHERE id=rid) IS DISTINCT FROM rev OR EXISTS(SELECT 1 FROM public.payroll_payslips WHERE pay_run_id=rid) OR EXISTS(SELECT 1 FROM public.payroll_financial_transactions WHERE pay_run_id=rid) THEN RAISE EXCEPTION 'Invalid bundle left partial writes';END IF;
  cfg:=public.v6226_set_payroll_review(true,0);
  denied:=false;BEGIN PERFORM public.v6226_set_payroll_review(false,0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale approval setting accepted';END IF;
  r:=public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(payload,'{finalise}','true'));rev:=(r->'run'->>'updated_at')::timestamptz;
  IF r->>'needs_approval'<>'true' OR r->'run'->>'status'<>'calculated' THEN RAISE EXCEPTION 'Approval requirement bypassed';END IF;
  r:=public.v6226_get_payroll_review(rid);hash:=r->'review'->>'source_hash';
  IF r->>'current'<>'true' OR jsonb_array_length(r->'employees')<>1 OR (SELECT count(*) FROM public.payroll_payslips WHERE pay_run_id=rid)<>1 OR EXISTS(SELECT 1 FROM public.accounting_journals WHERE business_id=bid AND source_type='payroll') THEN RAISE EXCEPTION 'Review snapshot or staging incorrect';END IF;
  denied:=false;BEGIN UPDATE public.payroll_pay_runs SET status='finalised' WHERE id=rid;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Old client bypassed approval';END IF;
  denied:=false;BEGIN PERFORM public.v6226_approve_pay_run(rid,hash);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Maker approved own run';END IF;
  UPDATE public.payroll_pay_run_employees SET hours=11 WHERE pay_run_id=rid;
  PERFORM set_config('request.jwt.claim.sub',reviewer::text,true);
  denied:=false;BEGIN PERFORM public.v6226_approve_pay_run(rid,hash);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Changed figures approved';END IF;
  PERFORM set_config('request.jwt.claim.sub',u::text,true);
  SELECT updated_at INTO rev FROM public.payroll_pay_runs WHERE id=rid;
  r:=public.v6226_save_pay_run(gen_random_uuid(),rid,rev,jsonb_set(payload,'{finalise}','true'));
  r:=public.v6226_get_payroll_review(rid);hash:=r->'review'->>'source_hash';
  PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
  denied:=false;BEGIN PERFORM public.v6226_approve_pay_run(rid,hash);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign caller approved payroll';END IF;
  PERFORM set_config('request.jwt.claim.sub',reviewer::text,true);
  r:=public.v6226_approve_pay_run(rid,hash);
  IF r->>'status'<>'finalised' OR (SELECT count(*) FROM public.accounting_journals WHERE business_id=bid AND source_type='payroll' AND source_id=rid)<>1 THEN RAISE EXCEPTION 'Approved payroll did not finalise and post once';END IF;
  PERFORM public.v6226_approve_pay_run(rid,hash);
  IF (SELECT count(*) FROM public.accounting_journals WHERE business_id=bid AND source_type='payroll' AND source_id=rid)<>1 THEN RAISE EXCEPTION 'Approval retry posted twice';END IF;
  BEGIN UPDATE public.payroll_pay_run_employees SET hours=12 WHERE pay_run_id=rid;EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%locked%' THEN RAISE;END IF;END;IF (SELECT hours FROM public.payroll_pay_run_employees WHERE pay_run_id=rid) IS DISTINCT FROM 10::numeric THEN RAISE EXCEPTION 'Finalised employee details changed';END IF;
  PERFORM public.v6226_set_payroll_review(false,1);
  payload:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{run,pay_run_number}','"FIXTURE-RUN-2"'),'{run,period_start}','"2026-10-08"'),'{run,period_end}','"2026-10-14"'),'{run,pay_date}','"2026-10-15"'),'{finalise}','true');
  payload:=jsonb_set(payload,'{employees,0,payslip,number}','"FIXTURE-RUN-2-FIXTURE"');
  r:=public.v6226_save_pay_run(gen_random_uuid(),NULL,NULL,payload);
  IF r->'run'->>'status'<>'finalised' OR r->>'needs_approval'<>'false' OR (SELECT count(*) FROM public.accounting_journals WHERE business_id=bid AND source_type='payroll')<>2 THEN RAISE EXCEPTION 'Approval-off finalisation changed';END IF;
  EXECUTE 'RESET ROLE';
  IF has_function_privilege('anon','public.v6226_save_pay_run(uuid,uuid,timestamptz,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.v6226_payroll_fingerprint(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Unsafe payroll API grants';END IF;
  RAISE EXCEPTION USING ERRCODE='P6226',MESSAGE='Rollback pay-run fixtures';
 EXCEPTION WHEN SQLSTATE 'P6226' THEN NULL;END;
 IF EXISTS(SELECT 1 FROM public.businesses WHERE id=bid) THEN RAISE EXCEPTION 'Fixture leaked';END IF;
 RAISE NOTICE 'Pay-run atomic and review fixtures passed; all changes rolled back';
END;$test$;
